import React, { useState, useEffect } from 'react';
import { documentService } from '../../services/documentService';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import {
  FileText,
  Search,
  Download,
  Loader,
  AlertCircle,
} from 'lucide-react';
import Swal from 'sweetalert2';

export const PublicDocumentsViewer = () => {
  const [documents, setDocuments] = useState([]);
  const [filteredDocuments, setFilteredDocuments] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Años disponibles (últimos 5 años)
  const years = Array.from({ length: 5 }, (_, i) => 
    new Date().getFullYear() - i
  );

  useEffect(() => {
    loadPublicDocuments();
  }, [selectedYear]);

  const loadPublicDocuments = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await documentService.getPublic({
        year: selectedYear.toString(),
      });
      setDocuments(data);
      setFilteredDocuments(data);
    } catch (err) {
      console.error('Error loading public documents:', err);
      setError('Error al cargar documentos públicos');
    } finally {
      setLoading(false);
    }
  };

  // Búsqueda con debounce
  useEffect(() => {
    const timer = setTimeout(() => {
      if (searchTerm.trim() === '') {
        setFilteredDocuments(documents);
      } else {
        const filtered = documents.filter(doc =>
          doc.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          doc.description.toLowerCase().includes(searchTerm.toLowerCase())
        );
        setFilteredDocuments(filtered);
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [searchTerm, documents]);

  const handleDownload = async (document) => {
    try {
      const blob = await documentService.download(document._id);
      const url = window.URL.createObjectURL(blob);
      const a = window.document.createElement('a');
      a.href = url;
      a.download = document.file_name;
      window.document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      window.document.body.removeChild(a);

      Swal.fire({
        icon: 'success',
        title: 'Descarga Iniciada',
        text: `Descargando ${document.file_name}`,
        timer: 2000,
        showConfirmButton: false,
      });
    } catch (error) {
      Swal.fire('Error', 'No se pudo descargar el documento', 'error');
    }
  };

  const getDocumentTypeIcon = (type) => {
    const icons = {
      report: '📊',
      certification: '✓',
      manual: '📖',
      permit: '📜',
    };
    return icons[type] || '📄';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center">
          <Loader className="w-12 h-12 animate-spin mx-auto mb-4 text-green-600" />
          <p className="text-gray-600">Cargando documentos públicos...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <Card className="border-red-200 bg-red-50">
        <CardContent className="p-8 text-center">
          <AlertCircle className="w-12 h-12 mx-auto text-red-600 mb-3" />
          <p className="text-red-600 font-semibold">{error}</p>
          <Button
            onClick={loadPublicDocuments}
            className="mt-4 bg-red-600 hover:bg-red-700"
          >
            Reintentar
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-900 mb-2">
          📚 Documentos Disponibles
        </h2>
        <p className="text-gray-600">
          Accede a la documentación pública de nuestros servicios
        </p>
      </div>

      {/* Filtros */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
          <Input
            placeholder="Buscar documentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>

        <select
          value={selectedYear}
          onChange={(e) => setSelectedYear(parseInt(e.target.value))}
          className="px-4 py-2 border rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent"
        >
          {years.map(year => (
            <option key={year} value={year}>
              Año {year}
            </option>
          ))}
        </select>
      </div>

      {/* Lista de documentos */}
      {filteredDocuments.length === 0 ? (
        <Card className="text-center py-12 bg-gray-50">
          <FileText className="w-16 h-16 mx-auto text-gray-300 mb-4" />
          <p className="text-gray-600 text-lg">
            {searchTerm ? 'No hay documentos que coincidan' : 'No hay documentos públicos disponibles'}
          </p>
        </Card>
      ) : (
        <div className="grid gap-4">
          {filteredDocuments.map((doc) => (
            <Card key={doc._id} className="hover:shadow-lg transition-shadow">
              <CardContent className="p-6">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3 mb-2">
                      <span className="text-2xl">
                        {getDocumentTypeIcon(doc.document_type)}
                      </span>
                      <div className="flex-1 min-w-0">
                        <h3 className="font-semibold text-gray-900 truncate">
                          {doc.title}
                        </h3>
                        {doc.client_id && (
                          <p className="text-xs sm:text-sm text-gray-500">
                            De: <span className="font-medium">{doc.client_id.company_name}</span>
                          </p>
                        )}
                      </div>
                    </div>

                    {doc.description && (
                      <p className="text-sm text-gray-600 line-clamp-2 mb-2">
                        {doc.description}
                      </p>
                    )}

                    <div className="flex flex-wrap items-center gap-2 text-xs text-gray-500">
                      <span className="inline-block bg-gray-100 px-2 py-1 rounded">
                        {doc.document_type}
                      </span>
                      <span>•</span>
                      <span>{new Date(doc.created_at).toLocaleDateString('es-ES')}</span>
                      <span>•</span>
                      <span>{(doc.file_size / 1024 / 1024).toFixed(2)} MB</span>
                      <span>•</span>
                      <span>Por: {doc.uploaded_by.full_name}</span>
                    </div>
                  </div>

                  <Button
                    onClick={() => handleDownload(doc)}
                    className="bg-green-600 hover:bg-green-700 flex-shrink-0 ml-2"
                    size="sm"
                  >
                    <Download className="w-4 h-4 mr-1" />
                    <span className="hidden sm:inline">Descargar</span>
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Resumen */}
      <Card className="bg-blue-50 border-blue-200">
        <CardContent className="p-4 text-sm text-blue-800">
          <p className="font-semibold mb-1">Documentos mostrados: {filteredDocuments.length}</p>
          <p>Filtrando por año {selectedYear} {searchTerm && `y búsqueda: "${searchTerm}"`}</p>
        </CardContent>
      </Card>
    </div>
  );
};

export default PublicDocumentsViewer;
